using System;
using System.Collections.Generic;

namespace AkaiS950Synth
{
    /// <summary>
    /// Whales: real whales, recorded - for ambient music, and for sleep.
    ///
    /// A first attempt at drawing whale song from arithmetic sounded like exactly that, and
    /// was dropped (the sea made for it was kept, on its own disk - see Ocean). These are
    /// recordings, and all of them are in the public domain, made by agencies of the United
    /// States government and published on Wikimedia Commons:
    ///
    ///   HUMPBACK, HUMPMOO  humpback calls, Glacier Bay, Alaska     National Park Service
    ///                      (Humpback_whale_moo.ogg)
    ///   BLOW               a humpback's wheezing blow, the same    National Park Service
    ///                      (Humpback_whale_wheezeblow.ogg)
    ///   ORCA               a killer whale call, Glacier Bay        National Park Service
    ///                      (Killer_whale_simple.ogg)
    ///   BLUE               a blue whale, North Atlantic            NOAA PMEL
    ///                      (Blue_whale_atlantic1.ogg; sped up to be heard)
    ///   FIN                a fin whale pulse, North Atlantic       NOAA PMEL
    ///                      (FinWhaleAtlantic-10x.ogg; sped up ten times)
    ///   MINKE              a minke whale's pulse train, Atlantic   NOAA PMEL
    ///                      (Atlantic_minke_whale_call.ogg)
    ///   SPERM              sperm whale clicks                      NOAA SWFSC
    ///                      (Sperm_Whale_Rapid_Clicks_and_Coda.ogg)
    ///
    /// Each is a short cut from its recording - a second or two, one call - faded in and
    /// out, cleared of rumble below 35 Hz, brought to the same loudness and kept as
    /// twelve-bit words: 12,000 Hz for the low calls, 16,000 Hz for the clicks, the orca and
    /// the blow, which go higher. The sea they were recorded in is still under them; that
    /// is part of the sound.
    ///
    /// The words are carried in this source as base64, as the birds are, so every build of
    /// the generator makes the same disk with no file beside it to find.
    ///
    /// THE PROGRAMMES. WHALES gives each call an octave of the keyboard, from C0, playing at
    /// its own pitch on the top key and an octave deeper at the bottom: whales are better
    /// slowed than hurried. SLOW WHALES is the same keyboard swelling in and dying away
    /// slowly, softened, to hold under ambient music. WHALE SEA adds the sea from the OCEAN
    /// disk on the octave below them, C-1 to B-1, so a song can have both from one disk. POD
    /// has them on a key each from C3, at their own pitch, as a kit.
    /// </summary>
    internal static class Whales
    {
        sealed class Recorded
        {
            public readonly string Name;
            public readonly int Rate;
            public readonly string Words;      // the twelve-bit words, little-endian int16, base64

            public Recorded(string name, int rate, string words) { Name = name; Rate = rate; Words = words; }

            public short[] Decode()
            {
                var bytes = Convert.FromBase64String(Words);
                var w = new short[bytes.Length / 2];
                Buffer.BlockCopy(bytes, 0, w, 0, bytes.Length);
                return w;
            }
        }

        static readonly Recorded[] Calls =
        {
            new Recorded("HUMPBACK", 12000,
                ""),
            new Recorded("HUMPMOO", 12000,
                ""),
            new Recorded("BLUE", 12000,
                ""),
            new Recorded("FIN", 12000,
                ""),
            new Recorded("MINKE", 12000,
                ""),
            new Recorded("ORCA", 16000,
                ""),
            new Recorded("SPERM", 16000,
                ""),
            new Recorded("BLOW", 16000,
                ""),
        };

        public static List<Patches.Wave> Waves()
        {
            var outp = new List<Patches.Wave>();
            for (int k = 0; k < Calls.Length; k++)
            {
                var c = Calls[k];
                outp.Add(new Patches.Wave
                {
                    Name = c.Name,
                    Rate = c.Rate,
                    Root = 35 + 12 * k,             // its own pitch on the top key of its octave
                    Oneshot = () => c.Decode()
                });
            }

            // the sea from the OCEAN disk, under the whales, its own pitch on the top key of the
            // octave below theirs
            outp.Add(new Patches.Wave { Name = "SEA", Rate = 16000, Root = 23, Looped = () => Ocean.Sea() });
            return outp;
        }

        public static List<Patch> Programmes()
        {
            var octaves = new List<Layer>();
            var pod = new List<Layer>();
            for (int k = 0; k < Calls.Length; k++)
            {
                octaves.Add(new Layer { Sample = Calls[k].Name, LowKey = 24 + 12 * k, HighKey = 35 + 12 * k });
                pod.Add(new Layer { Sample = Calls[k].Name, LowKey = 60 + k, HighKey = 60 + k });
            }

            return new List<Patch>
            {
                new Patch
                {
                    Name = "WHALES", A = 0, D = 99, S = 99, R = 40,
                    Filter = 99, KeyToFilter = 0, VelToFilter = 0, VelToLoudness = 25,
                    OneShot = true, Layers = octaves.ToArray()
                },

                // to hold under ambient music: in slowly, softened, out slowly
                new Patch
                {
                    Name = "SLOW WHALE", A = 50, D = 99, S = 99, R = 70,
                    Filter = 80, KeyToFilter = 0, VelToFilter = 10, VelToLoudness = 10,
                    Layers = octaves.ToArray()
                },

                // the whales over the sea: the same keyboard, and the sea on the octave below it,
                // to hold - for a song that wants both from one disk
                new Patch
                {
                    Name = "WHALE SEA", A = 30, D = 99, S = 99, R = 65,
                    Filter = 99, KeyToFilter = 0, VelToFilter = 0, VelToLoudness = 15,
                    Layers = WithSea(octaves)
                },

                new Patch
                {
                    Name = "POD", A = 0, D = 99, S = 99, R = 40,
                    Filter = 99, KeyToFilter = 0, VelToFilter = 0, VelToLoudness = 25,
                    OneShot = true, ConstantPitch = true, Layers = pod.ToArray()
                }
            };
        }

        static Layer[] WithSea(List<Layer> octaves)
        {
            var layers = new List<Layer>(octaves);
            layers.Add(new Layer { Sample = "SEA", LowKey = 12, HighKey = 23 });
            return layers.ToArray();
        }
    }
}
